def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    total_agents = 1 + len(alive_opponents)
    total_demand = WATER_REQ
    for opp in alive_opponents:
        total_demand += opp.get('water_requirement', WATER_REQ)

    scarcity = 0.0
    if total_demand > 0:
        scarcity = max(0.0, min(1.0, 1.0 - (float(supply) / float(total_demand))))

    prev_bids = []
    desperate_opp = False
    rich_opp_pressure = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opp = True
        opp_budget = opp.get('budget', 0)
        opp_salary = opp.get('daily_salary', DAILY_SALARY)
        if opp_budget >= opp_salary * 2:
            rich_opp_pressure = max(rich_opp_pressure, 1.0)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = DAILY_SALARY * 0.55
        avg_prev = DAILY_SALARY * 0.5

    urgency = 0.0
    if hp <= 2:
        urgency += 0.6
    elif hp <= 4:
        urgency += 0.35
    if no_water_days >= 1:
        urgency += 0.25
    urgency += scarcity * 0.45
    if desperate_opp:
        urgency += 0.1
    urgency = max(0.0, min(1.0, urgency))

    if hp <= 2 or no_water_days >= 2:
        target = max(DAILY_SALARY * 0.9, highest_prev + 2.0)
    elif scarcity > 0.45:
        target = max(DAILY_SALARY * 0.72, avg_prev + 1.5, highest_prev * 0.92)
    elif scarcity < 0.2 and hp > 4 and no_water_days == 0:
        target = max(DAILY_SALARY * 0.38, avg_prev * 0.82)
    else:
        target = max(DAILY_SALARY * (0.45 + 0.35 * urgency), avg_prev + 0.8)

    if rich_opp_pressure > 0 and scarcity > 0.35:
        target += 1.0

    reserve_days = 2 if hp > 3 else 1
    reserve = DAILY_SALARY * reserve_days
    max_affordable = budget - reserve
    if max_affordable < DAILY_SALARY * 0.2:
        max_affordable = budget

    bid = min(budget, max_affordable, target)
    floor_bid = 0.0
    if hp <= 3 or no_water_days >= 1:
        floor_bid = min(budget, DAILY_SALARY * 0.55)
    elif scarcity > 0.35:
        floor_bid = min(budget, DAILY_SALARY * 0.42)

    bid = max(floor_bid, bid)
    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Determine alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append(o)

    # If no opponents, bid modestly
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Base target bid: aim to win a meaningful share without overcommitting.
    # With supply 15-25 and our requirement 9, winning around 1 unit is often critical.
    # Convert supply to an estimate of how many full requirements exist.
    est_units = int(max(0.0, (float(supply) / float(WATER_REQ))))
    # If supply is near 15, est_units=1; near 25, est_units=2.

    # Aggression adjustment from opponents' yesterday bids (if available)
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If they were spending near salary, be more conservative if our hp is low.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if hp > 3.0:
                bid = DAILY_SALARY * 0.30
            else:
                bid = DAILY_SALARY * 0.70
        else:
            # Slightly outbid their apparent level to secure water.
            bid = max(DAILY_SALARY * 0.45, highest_prev_bid + 1.5)
    else:
        # No trace info: choose a mid-high bid early.
        # Increase slightly if we have accumulated no-water days.
        if no_water_days >= 2:
            bid = DAILY_SALARY * 0.70
        elif no_water_days == 1:
            bid = DAILY_SALARY * 0.60
        else:
            # Earlier days: more aggressive; later days: taper.
            if int(day) <= 3:
                bid = DAILY_SALARY * 0.62
            else:
                bid = DAILY_SALARY * 0.55

    # Ensure bid is feasible given budget
    bid = float(min(budget, bid))

    # If our budget is extremely low, bid whatever we can but keep it positive
    if bid <= 0.0:
        return 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        # If no opponents, bid very low to save budget, assuming water is guaranteed
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']

    # CRITICAL HEALTH: Prioritize survival above all else
    if my_current_hp <= 2:
        return min(my_current_budget, DAILY_SALARY * 0.95)

    # If no previous bids from opponents (e.g., Day 1 or new opponents)
    if not yesterday_bids:
        # Bid moderately if not in critical health
        return min(my_current_budget, DAILY_SALARY * 0.55)

    highest_prev_bid = max(yesterday_bids)

    # Scenario 1: Opponents bid very high yesterday, indicating tight competition
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_current_hp > 3: # Good health, can afford to be less aggressive to save budget
            return min(my_current_budget, DAILY_SALARY * 0.3)
        else: # Moderate health, still need water, bid high but slightly less than critical
            return min(my_current_budget, DAILY_SALARY * 0.88)

    # Scenario 2: Opponents bid moderately or low yesterday
    else:
        # Bid slightly above the highest previous bid to secure water,
        # ensuring a minimum bid to stay competitive.
        return min(my_current_budget, max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
